import React from 'react';
import dietitianImage from '../assets/dietitian-pradeepa.jpg';

const Hero = () => {
  return (
    <section className="bg-gray-50 py-16 px-4">
      <div className="container mx-auto">
        <h2 className="text-center text-4xl font-bold text-brand-orange mb-12">
          Getting to Know <br />
          <span className="text-brand-blue">"Coimbatore Dietitian Pradeepa"</span>
        </h2>
        <div className="flex flex-col md:flex-row gap-12 items-center">
          <div className="flex-1">
            <img src={dietitianImage} alt="Dietitian Pradeepa Saravanan" className="rounded-lg shadow-xl w-full max-w-md mx-auto" />
          </div>
          <div className="flex-1 space-y-4 text-lg leading-relaxed">
            <p><strong>Pradeepa Saravanan</strong> is a Coimbatore-based consultant Dietitian/Nutritionist...</p>
            <p>She says, Diet is the cornerstone of health and vitality...</p>
            <button className="bg-brand-green hover:bg-brand-green-dark text-white font-bold py-3 px-6 rounded-lg transition-colors mt-4">
              How do you feel being a dietitian?
            </button>
          </div>
        </div>
      </div>
    </section>
  );
};
